sp_widget.client_script:
api.controller = function (
	$scope,
	$rootScope,
	$injector,
	$timeout,
	DHManagerService,
	snAnalytics
) {
	/* widget controller */
	var c = this;
	var as, rootKBSub;
	c.loading = true;
	c.userAssets = null;
	c.euas = DHManagerService;
	c.actions = null;

	c.$onInit = function () {
		c.fieldMap = c.data.fieldMap;
		DHManagerService.fieldMap = c.fieldMap;

		//if we have no devices at all, don't start the process
		if(c.data.userAssets.length == 0) return;

		if (c.data.use_cc_kb && $injector.has("ccArticleService")) {
			var ccas = $injector.get("ccArticleService");

			as = ccas.articleStore.subscribe((article) => {
				if (article && article.sys_id) {
					c.kb_id = article.sys_id;
					getKbActions(article.sys_id);
				}
			});
		} else {
			rootKBSub = $rootScope.$watch("article_sys_id", (data) => {
				c.kb_id = data;
				getKbActions(data);
			});
		}
	};

	c.executeAction = async function (action) {
		await DHManagerService.executeAction(action);

		var payload = {};
		payload.name = "DH KB Action Executed";
		payload.data = {};
		payload.data["User id"] = c.data.user;
		payload.data["Action id"] = action.sys_id;
		payload.data["Action type"] = action.action_type;
		payload.data["KB Article"] = c.kb_id;
		snAnalytics.addEvent(payload);
	};

	var assetInfoSub = $scope.$watch(
		() => DHManagerService.assetInfo,
		(data) => {
			if (!data) return;

			//attach the extra device info
			c.userAssets = c.data.userAssets
				.map((asset) => {
				var details = data[asset.sys_id]?.details;
				asset.details = details;

				c.actions?.forEach((act) => {
					if (details?.ra_run_today) {
						act.run_today = details.ra_run_today.indexOf(act.sys_id) > -1;
					}
				});

				return asset;
			})
				.filter((a) => a?.details?.uid != null);

			DHManagerService.selectedAsset = c.userAssets[0].details.sys_id;
			$timeout(() => {
				c.loading = false;
			}, 650);
		}
	);

	$scope.$on("$destroy", () => {
		assetInfoSub();
		if (rootKBSub) rootKBSub();
		if (as) as();
	});

	async function getKbActions(article) {
		c.server
			.get({
			action: "get-actions",
			article: article,
		})
			.then(({ data }) => {
			if (data.actions.length) {
				c.actions = data.actions;
				DHManagerService.getMetrics(c.data.userAssets);
			}
		});
	}
};

sp_widget.css:
.loading {
  min-height: 10rem;
  width: 100%;
  border-radius: 1rem;
  background: lighten($brand-primary,43%);
  background-image: linear-gradient(
    to right,
    lighten($brand-primary,43%) 0%,
    lighten($brand-primary,30%) 20%,
    lighten($brand-primary,43%) 40%,
    lighten($brand-primary,43%) 100%
  );
  background-repeat: no-repeat;
  background-size: 10rem 5rem;
  animation: shimmer 2s infinite linear;
  transition: opacity 1s ease;
}

.panel.panel-default {
  border: none !important;
  //background: lighten($brand-primary,40%)!important;
  box-shadow: 0 0.4rem 0.8rem 0 rgba(23, 40, 52, 0.08);
  padding: 2.4rem;
}

.device-header.ng-hide-remove,
.device-selector.ng-hide-remove,
.action-container.ng-hide-remove,
.adh-kb-actions.ng-hide-remove {
  transition: opacity 1s ease;
  opacity: 0;
}

.device-header.ng-hide-remove.ng-hide-remove.ng-hide-remove-active,
.device-selector.ng-hide-remove.ng-hide-remove.ng-hide-remove-active,
.action-container.ng-hide-remove.ng-hide-remove.ng-hide-remove-active,
.adh-kb-actions.ng-hide-remove.ng-hide-remove.ng-hide-remove-active {
  opacity: 1;
}

.device-header {
  border-bottom: 1px solid #ccc;
  margin-bottom: 0.5rem;
  padding-bottom: 1.5rem;
}

.action-container {

  padding-top:1rem;

  button {
  width: 100%;
  }
}

.device-selector {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  align-items: center;

  small.label {
    line-height: inherit;
  }
}

@keyframes shimmer {
  0% {
    background-position: -1000px 0;
  }

  100% {
    background-position: 1000px 0;
  }
}

sp_widget.script:
(function () {
  var dh = new DeviceHealth();

  if (!input) {
    var pluginManager = new GlidePluginManager();
    var pluginId = "x_mukl_ec_article";

    data.use_cc_kb = pluginManager.isActive(pluginId);
    data.userAssets = dh.getUserDevices();
    data.fieldMap = dh.getMetricFieldLabelMaps();
    data.user = gs.getUserID();
  }

  if (input) {
    switch (input.action) {
      case "get-actions":
				if(!input.article) return;
        data.actions = getKbActions(input.article);
        break;
    }

    return;
  }

  function getKbActions(article) {
    const actions = new global.GlideQuery("x_mukl_dh_m2m_kb_actions")
      .where("kb_knowledge", article)
      .where("x_mukl_dh_actions.active", true)
      .select("x_mukl_dh_actions")
      .map((m2m_act) => {
        return m2m_act.x_mukl_dh_actions;
      })
      .toArray(10);

    return DHMetricCache.compileActions({
      actions: actions.toString(),
    });
  }
})();
